package com.exelynt.booking.config; import com.exelynt.booking.entity.User;import com.exelynt.booking.entity.Role;import com.exelynt.booking.repository.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import org.springframework.security.crypto.password.PasswordEncoder; @Configuration public class SeedDataConfig {@Bean CommandLineRunner seeds(UserRepository users,ResourceRepository resources,PasswordEncoder encoder){return x->{seed(users,encoder,"admin","admin@local.test","admin123",Role.ADMIN);seed(users,encoder,"user","user@local.test","user123",Role.USER);};}private void seed(UserRepository r,PasswordEncoder e,String n,String mail,String pass,Role role){if(r.findByUsername(n).isEmpty()){User u=new User();u.setUsername(n);u.setEmail(mail);u.setPassword(e.encode(pass));u.setRole(role);r.save(u);}}}
